<script setup lang="ts">
const api = useApi(), auth = useAuth(), notice = useNotice()
const admin = computed(() => auth.state.value.user?.role === 'admin'), status = ref<any>(null), busy = ref(false), setsBusy = ref(false)
const catalogue = reactive({ language: 'en', set_id: '' }), sets = ref<any[]>([]), setSearch = ref('')
const filteredSets = computed(() => sets.value.filter(s => (s.name + ' ' + s.id).toLowerCase().includes(setSearch.value.toLowerCase())))
const importFile = ref(''), importText = ref(''), importFormat = ref('json'), importMode = ref('max'), preview = ref<any>(null)
const password = reactive({ current_password: '', password: '' }), user = reactive({ name: '', email: '', password: '' }), users = ref<any[]>([])
let timer: ReturnType<typeof setTimeout> | undefined, alive = true, polling = false
async function refreshStatus() {
  if (!admin.value || !alive || polling) return
  clearTimeout(timer); polling = true
  try { const next = await api('/api/admin/status'); if (alive) status.value = next }
  catch (e) { if (alive && !status.value) notice.show(errorMessage(e), 'error') }
  finally { polling = false; if (alive) timer = setTimeout(refreshStatus, 5000) }
}
onMounted(async () => { refreshStatus(); if (admin.value) { try { users.value = await api('/api/admin/users') } catch (e) { notice.show(errorMessage(e), 'error') } } })
onBeforeUnmount(() => { alive = false; clearTimeout(timer) })
watch(() => catalogue.language, () => { sets.value = []; catalogue.set_id = '' })
watch(importMode, () => { preview.value = null })
const workerHealthy = computed(() => status.value?.worker_last_seen && Date.now() - Date.parse(status.value.worker_last_seen) < 120000)
async function loadSets() {
  setsBusy.value = true
  try { sets.value = await api('/api/admin/sets', { query: { language: catalogue.language } }) }
  catch (e) { notice.show(errorMessage(e), 'error') } finally { setsBusy.value = false }
}
async function queue(payload = catalogue) {
  busy.value = true
  try { const result = await api('/api/admin/imports', { method: 'POST', body: { language: payload.language, set_id: payload.set_id } }); notice.show(result.already_queued ? 'This set is already queued.' : 'Set import queued. Progress will appear below.'); clearTimeout(timer); await refreshStatus() }
  catch (e) { notice.show(errorMessage(e), 'error') } finally { busy.value = false }
}
async function chooseFile(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]
  preview.value = null; importText.value = ''; importFile.value = ''
  if (!file) return
  if (file.size > 2_000_000) { notice.show('Choose a file smaller than 2 MB.', 'error'); return }
  importFile.value = file.name; importFormat.value = file.name.toLowerCase().endsWith('.csv') ? 'csv' : 'json'
  importText.value = await file.text()
}
async function importCollection(apply = false) {
  busy.value = true
  try {
    const response = await api('/api/collection/import', { method: 'POST', body: { format: importFormat.value, text: importText.value, mode: importMode.value, apply } })
    preview.value = response
    if (apply) notice.show(`${response.changed} collection rows updated; ${response.rejected} rows skipped.`, response.rejected ? 'error' : 'success')
  } catch (e) { notice.show(errorMessage(e), 'error') } finally { busy.value = false }
}
async function changePassword() {
  busy.value = true
  try { await api('/api/password', { method: 'POST', body: { ...password } }); password.current_password = ''; password.password = ''; notice.show('Password changed. Other sessions have been signed out.') }
  catch (e) { notice.show(errorMessage(e), 'error') } finally { busy.value = false }
}
async function createUser() {
  busy.value = true
  try { await api('/api/admin/users', { method: 'POST', body: { ...user } }); Object.assign(user, { name: '', email: '', password: '' }); users.value = await api('/api/admin/users'); notice.show('Collector account created. Share the initial password securely.') }
  catch (e) { notice.show(errorMessage(e), 'error') } finally { busy.value = false }
}
</script>
<template><header class="page-heading"><div><span class="eyebrow">YOUR DATA, UNDER YOUR CONTROL</span><h1>Data & settings</h1><p>Bring in the cards. Keep a backup. Make this space yours.</p></div><span class="badge purple">CardShelf {{ status?.version || '…' }}</span></header><section v-if="admin" id="catalogue" class="panel settings-panel"><div class="section-heading"><div><h2>Catalogue imports</h2><p>Import complete sets from TCGdex into your own database.</p></div><span class="badge" :class="workerHealthy ? 'green' : 'amber'">{{ workerHealthy ? 'Worker online' : 'Worker not seen recently' }}</span></div><p v-if="!workerHealthy" class="alert warning">Imports need the background worker. Check <code>docker compose logs worker</code> on the server.</p><div class="import-set-controls"><label>Language<select v-model="catalogue.language"><option value="en">English</option><option value="ja">Japanese</option></select></label><button class="button secondary" :disabled="setsBusy" @click="loadSets"><AppIcon name="refresh" :size="17" />{{ setsBusy ? 'Loading…' : 'Load available sets' }}</button></div><div v-if="sets.length" class="form-columns"><label>Filter available sets<input v-model="setSearch" placeholder="Search set name or ID" /></label><label>Available sets<select v-model="catalogue.set_id"><option value="">Choose a set</option><option v-for="set in filteredSets" :key="set.id" :value="set.id">{{ set.name }} · {{ set.id }}</option></select></label></div><form class="import-set-controls" @submit.prevent="queue()"><label>TCGdex set ID<input v-model="catalogue.set_id" required pattern="[A-Za-z0-9][A-Za-z0-9._-]*" placeholder="e.g. base1" /></label><button class="button primary" :disabled="busy || !catalogue.set_id"><AppIcon name="download" :size="17" />Import set</button></form><p class="data-note">Card data is stored locally; artwork still loads from TCGdex’s image host. Variant flags are not a verified master checklist. Re-imports preserve your collection entries and manual printings.</p><div v-if="status?.jobs.length" class="jobs"><article v-for="job in status.jobs.slice(0, 10)" :key="job.id" class="job"><div class="job-heading"><strong>{{ job.kind === 'refresh-prices' ? 'Market prices' : job.payload.set_id }} <span class="badge">{{ job.payload.language?.toUpperCase() || job.payload.card_id || 'Tracked cards' }}</span></strong><span class="badge" :class="job.status === 'completed' ? 'green' : job.status === 'failed' ? 'red' : 'purple'">{{ job.status }}</span></div><div class="progress-track"><div :style="{ width: (job.total ? job.progress / job.total * 100 : 0) + '%' }" /></div><div class="job-summary"><small>{{ job.message }}<template v-if="job.total"> · {{ job.progress }}/{{ job.total }}</template></small><button v-if="job.status === 'failed' && job.kind === 'import-set'" class="text-button" :disabled="busy" @click="queue(job.payload)">Retry set</button></div><details v-if="job.errors?.length"><summary>{{ job.errors.length }} card errors</summary><p v-for="(error, i) in job.errors.slice(0, 20)" :key="i" class="small muted">{{ error.card_id }}: {{ error.message }}</p></details></article></div><div v-if="status" class="data-counts"><span>{{ status.counts.sets }} sets</span><span>{{ status.counts.cards.toLocaleString() }} cards</span><span>{{ status.counts.printings.toLocaleString() }} printings</span></div></section><div class="settings-columns"><section class="panel settings-panel"><div class="section-heading"><div><h2>Export your collection</h2><p>Take your ownership records with you.</p></div><AppIcon name="download" /></div><div class="button-row"><a class="button secondary" href="/api/collection/export?format=json" download><AppIcon name="download" :size="17" />Collection JSON</a><a class="button secondary" href="/api/collection/export?format=csv" download><AppIcon name="download" :size="17" />Collection CSV</a></div><p class="data-note">These exports contain quantities, conditions, wishlists and notes. They do not include binder layouts, accounts or the full catalogue. Use the database backup script for a complete server backup.</p></section><section class="panel settings-panel"><div class="section-heading"><div><h2>Server backup</h2><p>A complete copy, not just a collection export.</p></div><AppIcon name="shield" /></div><p class="muted small">Run from the package directory on your server:</p><pre class="code-block">sh scripts/backup.sh</pre><p class="data-note">Back up the generated database dump and your .env file securely off-server. Backup scheduling is not automatic in this release. Restore instructions are in docs/DEPLOYMENT.md.</p></section></div><section class="panel settings-panel"><div class="section-heading"><div><h2>Import ownership records</h2><p>Preview matches before applying any changes.</p></div><AppIcon name="upload" /></div><div class="form-columns"><label>CardShelf JSON or compatible CSV<input type="file" accept=".json,.csv,application/json,text/csv" @change="chooseFile" /><small>Maximum 2 MB / 5,000 rows. Import the corresponding catalogue sets first.</small></label><label>Merge method<select v-model="importMode"><option value="max">Safe merge — keep the higher quantity</option><option value="replace">Replace quantities in matched rows</option></select><small>{{ importMode === 'max' ? 'Repeated imports do not add duplicate copies. Existing non-empty notes are retained.' : 'Overwrites quantity, wishlist and notes for matched rows. Other rows are untouched.' }}</small></label></div><p class="data-note">This importer uses CardShelf’s documented schema. BinderBuilder exports are not assumed to be compatible.</p><button class="button secondary" :disabled="busy || !importText" @click="importCollection(false)">Preview {{ importFile || 'import' }}</button><div v-if="preview" class="import-preview"><div class="button-row"><span class="badge green">{{ preview.matched }} matched rows</span><span class="badge" :class="preview.rejected ? 'amber' : ''">{{ preview.rejected }} skipped rows</span><span v-if="preview.applied" class="badge purple">{{ preview.changed }} rows updated</span></div><p v-if="preview.rejected" class="alert warning">Only matched rows will be imported. Unresolved or invalid rows below will be skipped; they are not silently converted.</p><div v-if="preview.errors.length" class="error-list"><p v-for="error in preview.errors" :key="error.row" class="small"><strong>Row {{ error.row }}:</strong> {{ error.message }}</p></div><div v-if="preview.sample.length" class="table-scroll"><table><thead><tr><th>Card ID</th><th>Printing key</th><th>Condition</th><th>Quantity</th></tr></thead><tbody><tr v-for="row in preview.sample" :key="row.row"><td>{{ row.language }}:{{ row.card_id }}</td><td>{{ row.printing }}</td><td>{{ row.condition }}</td><td>{{ row.quantity }}</td></tr></tbody></table><p class="muted small">Preview shows up to 15 matched rows.</p></div><button class="button primary" :disabled="busy || !preview.matched || preview.applied" @click="importCollection(true)">Apply {{ preview.matched }} matched rows</button></div></section><div class="settings-columns"><section class="panel settings-panel"><h2>Change your password</h2><p class="muted small">Other signed-in sessions will be revoked.</p><form class="form-stack" @submit.prevent="changePassword"><label>Current password<input v-model="password.current_password" type="password" required autocomplete="current-password" maxlength="128" /></label><label>New password<input v-model="password.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" /><small>At least 12 characters.</small></label><button class="button secondary" :disabled="busy">Update password</button></form></section><section v-if="admin" class="panel settings-panel"><h2>Add a collector</h2><p class="muted small">Each collector has private ownership records and binders. The catalogue is shared.</p><form class="form-stack" @submit.prevent="createUser"><label>Name<input v-model="user.name" required maxlength="80" /></label><label>Email<input v-model="user.email" type="email" required maxlength="254" /></label><label>Initial password<input v-model="user.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" /></label><button class="button secondary" :disabled="busy">Create collector account</button></form><details class="spaced"><summary>{{ users.length }} account(s)</summary><p v-for="account in users" :key="account.id" class="small">{{ account.name }} · {{ account.email }} <span class="badge">{{ account.role }}</span></p></details></section></div></template>